#!/usr/bin/env bash
# Creates local-dev/.env with random local-only secrets. Never overwrites an existing .env: the PostgreSQL volume
# keeps the passwords it was created with, so changing them later needs `docker compose down -v` (deletes local data).
set -euo pipefail
cd "$(dirname "$0")"
if [[ -e .env ]]; then echo ".env already exists; leaving it unchanged" >&2; exit 0; fi
rand() { openssl rand -base64 48 | tr -dc 'A-Za-z0-9' | head -c "${1:-40}"; }
hex() { openssl rand -hex 16; }
umask 077
cat > .env <<ENV
# Local-only values generated by init-env.sh. Not for any shared or production environment. Do not commit.
LOCAL_TENANT_ID=00000000-0000-4000-8000-000000000001
LOCAL_TENANT_KEY=local
LOCAL_TENANT_NAME=Local
LOCAL_ADMIN_USERNAME=admin
LOCAL_ADMIN_PASSWORD=$(rand 20)
LOCAL_POSTGRES_PORT=15432

POSTGRES_SUPERUSER_PASSWORD=$(rand)
IDENTITY_DB_PASSWORD=$(rand)
ERP_DB_PASSWORD=$(rand)
WORKFLOW_DB_PASSWORD=$(rand)
MONITOR_DB_PASSWORD=$(rand)
REDIS_PASSWORD=$(rand)
IDENTITY_KEY_ENCRYPTION_PASSWORD=$(rand 48)
IDENTITY_KEY_ENCRYPTION_SALT=$(hex)
IDENTITY_SERVICE_CLIENT_SECRET=$(rand 48)
ERP_BFF_CLIENT_SECRET=$(rand 48)
ERP_SERVICE_CLIENT_SECRET=$(rand 48)
ERP_SESSION_ENCRYPTION_PASSWORD=$(rand 48)
ERP_SESSION_ENCRYPTION_SALT=$(hex)
ENV
echo "created $(pwd)/.env  (login: admin / $(grep '^LOCAL_ADMIN_PASSWORD=' .env | cut -d= -f2))"
